#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <errno.h>

void *worker_function(void *arg) {
    printf("Worker thread: Running a task.\n");
    sleep(1); // Simulate time-consuming work
    printf("Worker thread: Task completed. Resources will be freed automatically.\n");
    return NULL;
}

int main() {
    pthread_t worker_id;
    int s;

    // 1. Create a joinable thread
    s = pthread_create(&worker_id, NULL, worker_function, NULL);
    if (s != 0) {
        errno = s;
        perror("pthread_create");
        return 1;
    }

    // 2. Mark the newly created thread as detached
    s = pthread_detach(worker_id);

    if (s != 0) {
        errno = s;
        perror("pthread_detach");
        // Note: Thread may still be running, but we must exit due to failure
        return 1;
    }

    printf("Main thread: Successfully detached worker thread ID %lu.\n", (unsigned long)worker_id);

    // The main thread cannot call pthread_join(worker_id) now.
    // We sleep to ensure the detached worker thread has time to execute 
    // before the main process terminates and cleans up everything.
    sleep(2); 

    printf("Main thread: Exiting.\n");
    return 0;
}
